/**
 * P2-LAZY-B1 static proof: App.jsx lazy AdaptiveLayoutEngine + dist chunk.
 */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const repoRoot = path.join(__dirname, '../../..');
const appPath = path.join(repoRoot, 'src/renderer/src/App.jsx');
const distJs = path.join(repoRoot, 'dist-renderer/js');
const indexHtml = path.join(repoRoot, 'dist-renderer/index.html');

const app = fs.readFileSync(appPath, 'utf8');

const lazyNeedle = "const AdaptiveLayoutEngine = React.lazy(() => import('./components/AdaptiveLayoutEngine.jsx'))";
assert.ok(app.includes(lazyNeedle), 'missing lazy AdaptiveLayoutEngine import');
assert.ok(!app.includes("import AdaptiveLayoutEngine from './components/AdaptiveLayoutEngine.jsx'"), 'eager AdaptiveLayoutEngine import remains');

assert.ok(app.includes("panels.isOpen('adaptive-layout')"), 'panel-gated mount missing');
assert.ok(app.includes("panels.open('adaptive-layout')"), 'panel open path missing');
assert.ok(app.includes('synchronizeAppLayoutFromAdaptiveEngine'), 'sync helper missing');
assert.ok(app.includes('handleAdaptiveLayout'), 'apply handler missing');
assert.ok(app.includes('ADAPTIVE_LAYOUT_TO_RAIL_PRESET'), 'rail preset map unused');
assert.ok(app.includes("command === '/layout'"), '/layout slash route missing');

const chunkNames = fs.readdirSync(distJs).filter((f) => f.endsWith('.js'));
const aleChunk = chunkNames.find((n) => n.startsWith('AdaptiveLayoutEngine-'));
assert.ok(aleChunk, 'missing dist chunk for AdaptiveLayoutEngine');

const html = fs.readFileSync(indexHtml, 'utf8');
assert.ok(!html.includes('CyhV27Wm') && !html.includes('DRb2Vx79'), 'stale bundle hashes in index.html');
const indexEntry = chunkNames.find((n) => n.startsWith('index-'));
assert.ok(html.includes(`./js/${indexEntry}`), 'index.html must reference current index chunk');

const aleBytes = fs.statSync(path.join(distJs, aleChunk)).size;
const indexSize = fs.statSync(path.join(distJs, indexEntry)).size;
const report = {
    adaptiveLayoutChunk: aleChunk,
    adaptiveLayoutBytes: aleBytes,
    adaptiveLayoutKB: Math.round((aleBytes / 1024) * 100) / 100,
    indexChunk: indexEntry,
    indexBytes: indexSize,
    indexKB: Math.round(indexSize / 1024),
    totalJsChunks: chunkNames.length,
    staleHashesAbsent: true,
};

fs.writeFileSync(
    path.join(__dirname, 'build-report.json'),
    `${JSON.stringify(report, null, 2)}\n`,
);

