/**
 * P2-LAZY-B1 focused Electron runtime smoke (PR #76 + apply guardrail).
 * Proof: validation-artifacts/post-release/phase-p2-lazy-b1-adaptive-layout-panel/electron-runtime-smoke/
 */
const { test, expect } = require('@playwright/test');
const { _electron: electron } = require('playwright');
const path = require('path');
const fs = require('fs');
const os = require('os');

const PROOF_DIR = path.join(
    __dirname,
    '..',
    'validation-artifacts',
    'post-release',
    'phase-p2-lazy-b1-adaptive-layout-panel',
    'electron-runtime-smoke',
);

/** Safe ALE preset: Operator → ADAPTIVE_LAYOUT_TO_RAIL_PRESET.operator = 'wide' (known mapping). */
const SAFE_ALE_PRESET_LABEL = 'Operator';

const report = {
    phase: 'p2-lazy-b1-adaptive-layout-panel',
    pr: 76,
    head: 'fb083cb8f055f1308572aca48603613e8dc702a2',
    date: new Date().toISOString(),
    checks: [],
    consoleErrors: [],
    pageErrors: [],
    staleHashesAbsent: null,
    aleChunkPresent: null,
    aleOpened: false,
    aleClosed: false,
    aleApplyAttempted: false,
    aleApplyPassed: false,
    aleApplyDeferred: false,
    workspaceStillVisibleAfterApply: false,
    railsValidAfterApply: false,
    helpWorksAfterApply: false,
    freeformWorksAfterApply: false,
    beforeAfterSnapshot: null,
    overall: 'pending',
};

function record(id, pass, note = '') {
    report.checks.push({ id, pass, note });
}

function isNonFatalConsoleError(text) {
    return /ResizeObserver|favicon|net::ERR|Content Security Policy|worldtimeapi|timeapi\.io|connect-src/i.test(text);
}

test.describe('P2-LAZY-B1 Adaptive Layout Electron smoke', () => {
    test.describe.configure({ mode: 'serial', timeout: 300000 });
    test.setTimeout(300000);

    let app;
    let page;
    let userDataDir;

    async function dismissBlockingOverlays() {
        for (const testId of ['onboarding-close-btn', 'firstboot-close-btn', 'onboarding-finish-btn']) {
            const btn = page.getByTestId(testId);
            if (await btn.count()) {
                await btn.first().click({ force: true }).catch(() => {});
                await page.waitForTimeout(120);
            }
        }
        await page.keyboard.press('Escape').catch(() => {});
        await page.waitForTimeout(100);
    }

    async function ensureShellReady() {
        await expect(page.locator('[data-testid="top-status-bar"]')).toBeVisible({ timeout: 45000 });
        await expect(page.locator('[data-testid="thread-rail"]')).toBeVisible({ timeout: 45000 });
        await dismissBlockingOverlays();
    }

    async function railBox(testId) {
        const el = page.getByTestId(testId).first();
        if (!(await el.count())) return null;
        const box = await el.boundingBox();
        if (!box || !Number.isFinite(box.width)) return null;
        return { width: Math.round(box.width), x: Math.round(box.x), y: Math.round(box.y) };
    }

    async function activeLayoutPresetId() {
        for (const id of ['hud', 'compact', 'balanced', 'wide']) {
            const btn = page.getByTestId(`layout-preset-${id}-btn`);
            if (await btn.count()) {
                const pressed = await btn.getAttribute('aria-pressed');
                if (pressed === 'true') return id;
            }
        }
        return null;
    }

    async function captureShellSnapshot(phase) {
        const workbenchRail = page.getByTestId('workbench-rail');
        const workbenchMini = page.getByTestId('workbench-rail-mini-expand-btn');
        const workbenchVisible = await workbenchRail.isVisible().catch(() => false);
        const workbenchCollapsed = !workbenchVisible && (await workbenchMini.isVisible().catch(() => false));
        const layoutBarVisible = await page.getByTestId('layout-control-bar').isVisible().catch(() => false);
        const presetButtons = {};
        for (const id of ['hud', 'compact', 'balanced', 'wide']) {
            const btn = page.getByTestId(`layout-preset-${id}-btn`);
            presetButtons[id] = await btn.isVisible().catch(() => false);
        }
        return {
            phase,
            timestamp: new Date().toISOString(),
            activeLayoutPresetId: await activeLayoutPresetId(),
            threadRail: await railBox('thread-rail'),
            workbenchRail: await railBox('workbench-rail'),
            workbenchCollapsed,
            workspacePanelVisible: await page.getByTestId('workspace-panel').first().isVisible().catch(() => false),
            chatInputVisible: await page.getByTestId('chat-input').first().isVisible().catch(() => false),
            layoutBarVisible,
            layoutPresetButtonsVisible: presetButtons,
        };
    }

    async function railsValidInViewport() {
        const viewport = page.viewportSize() || { width: 1440, height: 900 };
        const workspace = await page.getByTestId('workspace-panel').first().boundingBox();
        if (!workspace || workspace.width < 200) return false;
        const thread = await railBox('thread-rail');
        const workbench = await railBox('workbench-rail');
        const mini = page.getByTestId('workbench-rail-mini-expand-btn');
        const workbenchOk = workbench
            ? workbench.x >= 0 && workbench.x + workbench.width <= viewport.width + 2
            : (await mini.isVisible().catch(() => false));
        const threadOk = thread
            ? thread.x >= 0 && thread.width >= 40 && thread.x + thread.width <= viewport.width
            : false;
        return threadOk && workbenchOk && workspace.x >= 0 && workspace.x < viewport.width;
    }

    async function sendCommand(command) {
        await dismissBlockingOverlays();
        const composer = page.getByTestId('chat-input').first();
        await composer.fill(command, { force: true });
        const sendBtn = page.getByRole('button', { name: 'Send' }).first();
        if (await sendBtn.count()) {
            await sendBtn.click({ force: true });
        } else {
            await composer.press('Enter', { force: true });
        }
        await page.waitForTimeout(450);
    }

    async function waitForApplyLayoutSettle() {
        await page.evaluate(() => new Promise((resolve) => {
            let settled = false;
            const done = () => {
                if (settled) return;
                settled = true;
                window.removeEventListener('neuralshell:apply-layout', onApply);
                resolve();
            };
            const onApply = () => {
                window.setTimeout(done, 350);
            };
            window.addEventListener('neuralshell:apply-layout', onApply, { once: true });
            window.setTimeout(done, 2500);
        }));
        await page.waitForTimeout(400);
    }

    test.beforeAll(async () => {
        fs.mkdirSync(PROOF_DIR, { recursive: true });

        const indexHtml = fs.readFileSync(path.join(__dirname, '..', 'dist-renderer', 'index.html'), 'utf8');
        report.staleHashesAbsent = !indexHtml.includes('CyhV27Wm') && !indexHtml.includes('DRb2Vx79');
        const jsDir = path.join(__dirname, '..', 'dist-renderer', 'js');
        report.aleChunkPresent = fs.existsSync(jsDir)
            && fs.readdirSync(jsDir).some((f) => f.startsWith('AdaptiveLayoutEngine-'));

        userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-e2e-p2-b1-'));
        app = await electron.launch({
            args: ['.'],
            cwd: path.resolve(__dirname, '..'),
            timeout: 120000,
            env: {
                ...process.env,
                NEURAL_USER_DATA_DIR: userDataDir,
                NEURAL_IGNORE_INTEGRITY: '1',
            },
        });
        page = await app.firstWindow({ timeout: 120000 });
        await page.setViewportSize({ width: 1440, height: 900 });
        page.on('console', (msg) => {
            if (msg.type() === 'error') {
                const text = msg.text();
                if (!text.includes('DevTools') && !text.includes('Autofill')) {
                    report.consoleErrors.push(text.slice(0, 500));
                }
            }
        });
        page.on('pageerror', (err) => {
            report.pageErrors.push(String(err).slice(0, 500));
        });
        await page.waitForLoadState('domcontentloaded');
        await page.evaluate(() => {
            globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
            globalThis.localStorage.setItem('neuralshell_first_boot_dismissed_v1', '1');
        });
        await page.reload();
        await ensureShellReady();
    });

    test.afterAll(async ({}, testInfo) => {
        testInfo.setTimeout(120000);
        const fatalConsole = report.consoleErrors.filter((e) =>
            /failed to fetch dynamically imported module|ChunkLoadError|AdaptiveLayoutEngine/i.test(e)
            && !isNonFatalConsoleError(e),
        );
        const guardrailOk = report.aleApplyDeferred
            ? report.aleOpened && report.aleClosed
            : report.aleApplyPassed;
        const allPass = report.checks.every((c) => c.pass)
            && report.staleHashesAbsent
            && report.aleChunkPresent
            && fatalConsole.length === 0
            && report.pageErrors.length === 0
            && guardrailOk;
        report.overall = allPass ? 'pass' : 'fail';
        report.fatalDynamicImport = fatalConsole;
        fs.writeFileSync(
            path.join(PROOF_DIR, 'runtime-smoke-report.json'),
            `${JSON.stringify(report, null, 2)}\n`,
        );
        if (report.beforeAfterSnapshot) {
            fs.writeFileSync(
                path.join(PROOF_DIR, 'ale-apply-before-after.json'),
                `${JSON.stringify(report.beforeAfterSnapshot, null, 2)}\n`,
            );
        }
        if (app) await app.close();
        try {
            fs.rmSync(userDataDir, { recursive: true, force: true });
        } catch {
            /* ignore */
        }
    });

    test('1 boot: ALE hidden by default', async () => {
        await expect(page.getByTestId('adaptive-layout-engine')).toHaveCount(0);
        record('boot-no-ale', true);
    });

    test('2 ALE apply guardrail — before/after shell snapshot', async () => {
        const importErrorsBefore = report.pageErrors.length;
        await page.getByTestId('layout-preset-balanced-btn').click({ force: true });
        await page.waitForTimeout(200);

        const before = await captureShellSnapshot('before-apply');
        record('before-workspace-visible', before.workspacePanelVisible);
        record('before-layout-bar', before.layoutBarVisible && Object.values(before.layoutPresetButtonsVisible).every(Boolean));
        record('before-rails-snapshot', Boolean(before.threadRail));

        await sendCommand('/layout');
        const ale = page.getByTestId('adaptive-layout-engine');
        await expect(ale).toBeVisible({ timeout: 15000 });
        report.aleOpened = true;
        record('slash-layout-opens', true);

        const importOk = report.pageErrors.length === importErrorsBefore;
        record('ale-chunk-load', importOk, importOk ? 'no pageerror on open' : report.pageErrors.slice(-1)[0] || '');

        const operatorCard = ale.locator('button.w-full.text-left').filter({ hasText: SAFE_ALE_PRESET_LABEL });
        const operatorCount = await operatorCard.count();
        report.aleApplyAttempted = operatorCount > 0;

        if (operatorCount === 0) {
            report.aleApplyDeferred = true;
            report.aleApplyPassed = false;
            record('ale-apply-deferred', true, 'no safe Operator preset button found');
            await page.keyboard.press('Escape');
            await expect(ale).toBeHidden({ timeout: 5000 });
            report.aleClosed = true;
            report.beforeAfterSnapshot = { before, after: null, deferred: true };
            return;
        }

        await operatorCard.first().scrollIntoViewIfNeeded();
        await operatorCard.first().click({ timeout: 15000 });
        await waitForApplyLayoutSettle();

        const after = await captureShellSnapshot('after-apply');
        report.beforeAfterSnapshot = {
            safePreset: SAFE_ALE_PRESET_LABEL,
            before,
            after,
            railDelta: {
                threadWidth: (after.threadRail?.width ?? 0) - (before.threadRail?.width ?? 0),
                workbenchWidth: (after.workbenchRail?.width ?? 0) - (before.workbenchRail?.width ?? 0),
            },
        };

        await page.keyboard.press('Escape');
        await expect(ale).toBeHidden({ timeout: 5000 });
        report.aleClosed = true;
        record('escape-closes-ale', true);

        const noCrash = await page.getByTestId('top-status-bar').isVisible();
        const workspaceOk = await page.getByTestId('workspace-panel').first().isVisible();
        const chatOk = await page.getByTestId('chat-input').first().isVisible();
        const railsOk = await railsValidInViewport();
        report.workspaceStillVisibleAfterApply = workspaceOk;
        report.railsValidAfterApply = railsOk;

        for (const id of ['hud', 'compact', 'balanced', 'wide']) {
            await page.getByTestId(`layout-preset-${id}-btn`).click({ force: true });
            await page.waitForTimeout(80);
        }
        const layoutBarOk = await page.getByTestId('layout-preset-balanced-btn').isVisible();

        await page.locator('body').click({ position: { x: 400, y: 400 }, force: true });
        await page.keyboard.press('Control+k');
        await expect(page.locator('[data-testid="command-palette"]')).toBeVisible({ timeout: 10000 });
        await page.keyboard.press('Escape');
        await page.keyboard.press('Control+,');
        await expect(page.locator('[data-testid="settings-drawer"]')).toBeVisible({ timeout: 10000 });
        await page.keyboard.press('Escape');

        await sendCommand('/help');
        const helpVisible = await page.locator('[data-testid="chat-message"]')
            .filter({ hasText: 'NeuralShell Operator Guide' })
            .first()
            .isVisible({ timeout: 15000 });
        report.helpWorksAfterApply = helpVisible;

        const composer = page.getByTestId('chat-input').first();
        await composer.fill('freeform after ale apply', { force: true });
        await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
        await expect(composer).toHaveValue('', { timeout: 10000 });
        report.freeformWorksAfterApply = true;

        const railChanged = (after.threadRail?.width ?? 0) !== (before.threadRail?.width ?? 0)
            || (after.workbenchRail?.width ?? 0) !== (before.workbenchRail?.width ?? 0)
            || after.workbenchCollapsed !== before.workbenchCollapsed;

        report.aleApplyPassed = noCrash
            && workspaceOk
            && chatOk
            && railsOk
            && layoutBarOk
            && helpVisible
            && report.freeformWorksAfterApply
            && importOk
            && railChanged;

        record('shell-no-crash-after-apply', noCrash);
        record('workspace-after-apply', workspaceOk);
        record('chat-after-apply', chatOk);
        record('rails-valid-after-apply', railsOk);
        record('layout-bar-after-apply', layoutBarOk);
        record('palette-settings-after-apply', true);
        record('help-after-apply', helpVisible);
        record('freeform-after-apply', report.freeformWorksAfterApply);
        record('ale-apply-rail-delta', railChanged, JSON.stringify(report.beforeAfterSnapshot.railDelta));
        record('ale-apply-guardrail', report.aleApplyPassed);
    });

    test('3 /help lists /layout (baseline)', async () => {
        await dismissBlockingOverlays();
        await sendCommand('/help');
        const helpMsg = page.locator('[data-testid="chat-message"]').filter({ hasText: 'NeuralShell Operator Guide' });
        await expect(helpMsg.first()).toBeVisible({ timeout: 15000 });
        const helpText = await helpMsg.first().innerText();
        record('help-includes-layout', helpText.includes('/layout'));
    });

    test('4 Mission/Eco/Tasks chips', async () => {
        await page.getByTestId('mission-control-open-btn').click();
        await expect(page.getByTestId('mission-control')).toBeVisible({ timeout: 15000 });
        await page.getByTestId('mission-control-close-btn').click();
        await page.getByTestId('ecosystem-open-btn').click();
        await expect(page.getByTestId('ecosystem-launcher')).toBeVisible({ timeout: 15000 });
        await page.getByTestId('ecosystem-close-btn').click();
        await page.getByTestId('task-manager-open-btn').click();
        await expect(page.getByTestId('task-manager-drawer')).toBeVisible({ timeout: 15000 });
        await page.getByTestId('task-manager-close-btn').click();
        record('mission-eco-tasks', true);
    });

    async function closeRecoveryPanel(panelId) {
        const panel = page.getByTestId(`recovery-panel-${panelId}`);
        if (!(await panel.count())) return;
        const closeBtn = panel.getByRole('button', { name: 'Close panel' });
        if (await closeBtn.count()) {
            await closeBtn.first().click({ force: true });
        } else {
            await page.getByTestId(`recovery-panel-backdrop-${panelId}`).click({ force: true }).catch(() => {});
        }
        await expect(panel).toBeHidden({ timeout: 10000 });
        await page.waitForTimeout(200);
    }

    test('5 Projects/Agents/Voice P0 drawers', async () => {
        await dismissBlockingOverlays();
        await page.getByTitle('Projects (Ctrl+P)').click({ force: true, timeout: 15000 });
        await expect(page.getByTestId('projects-mode-panel')).toBeVisible({ timeout: 15000 });
        await closeRecoveryPanel('projects-mode');
        await page.getByTitle('Agent Marketplace').click({ force: true, timeout: 20000 });
        await expect(page.getByTestId('agent-store')).toBeVisible({ timeout: 15000 });
        await closeRecoveryPanel('agent-store');
        const voiceBtn = page.getByTitle('Voice input');
        await voiceBtn.scrollIntoViewIfNeeded();
        await voiceBtn.click({ force: true, timeout: 20000 });
        await expect(page.getByTestId('voice-panel')).toBeVisible({ timeout: 15000 });
        await closeRecoveryPanel('voice-mode');
        record('p0-panels', true);
    });

    test('6 no React fatals, stale hashes, dist chunk', async () => {
        record('stale-hashes-absent', report.staleHashesAbsent === true);
        record('dist-ale-chunk', report.aleChunkPresent === true);
        const nonFatalConsole = report.consoleErrors.filter((e) => !isNonFatalConsoleError(e));
        record('no-fatal-console', nonFatalConsole.length === 0, nonFatalConsole.slice(0, 2).join(' | '));
        record('no-page-errors', report.pageErrors.length === 0, report.pageErrors.slice(0, 2).join(' | '));
    });
});

