/**
 * P2-LAZY-B2 focused runtime smoke (local proof, gitignored).
 */
const { _electron: electron } = require('playwright');
const fs = require('fs');
const path = require('path');
const os = require('os');

const PROOF_DIR = __dirname;
const repoRoot = path.join(__dirname, '../../..');

async function main() {
    const report = {
        phase: 'p2-lazy-b2-adaptive-layout-chip',
        date: new Date().toISOString(),
        checks: [],
        overall: 'fail',
    };
    const record = (id, pass, note = '') => report.checks.push({ id, pass, note });

    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-b2-chip-'));
    const app = await electron.launch({
        args: ['.'],
        cwd: repoRoot,
        env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1' },
    });
    const page = await app.firstWindow();
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.evaluate(() => {
        globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        globalThis.localStorage.setItem('neuralshell_first_boot_dismissed_v1', '1');
    });
    await page.reload();
    await page.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 45000 });

    const chip = page.getByTestId('adaptive-layout-open-btn');
    record('layout-chip-visible-lg', await chip.isVisible());
    await chip.click();
    await page.getByTestId('adaptive-layout-engine').waitFor({ state: 'visible', timeout: 15000 });
    record('layout-chip-opens-ale', true);
    await page.keyboard.press('Escape');
    await page.getByTestId('adaptive-layout-engine').waitFor({ state: 'hidden', timeout: 5000 });
    record('escape-closes-ale', true);

    const composer = page.getByTestId('chat-input').first();
    await composer.fill('/layout', { force: true });
    await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
    await page.getByTestId('adaptive-layout-engine').waitFor({ state: 'visible', timeout: 15000 });
    record('slash-layout-still-works', true);
    await page.keyboard.press('Escape');

    await page.getByTestId('mission-control-open-btn').click();
    await page.getByTestId('mission-control').waitFor({ state: 'visible' });
    await page.getByTestId('mission-control-close-btn').click();
    await page.getByTestId('ecosystem-open-btn').click();
    await page.getByTestId('ecosystem-launcher').waitFor({ state: 'visible' });
    await page.getByTestId('ecosystem-close-btn').click();
    await page.getByTestId('task-manager-open-btn').click();
    await page.getByTestId('task-manager-drawer').waitFor({ state: 'visible' });
    await page.getByTestId('task-manager-close-btn').click();
    record('mission-eco-tasks', true);

    await page.locator('body').click({ position: { x: 400, y: 400 }, force: true });
    await page.keyboard.press('Control+k');
    await page.getByTestId('command-palette').waitFor({ state: 'visible' });
    await page.keyboard.press('Escape');
    await page.keyboard.press('Control+,');
    await page.getByTestId('settings-drawer').waitFor({ state: 'visible' });
    await page.keyboard.press('Escape');
    record('exec-settings', true);

    await composer.fill('/help', { force: true });
    await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
    await page.getByText('NeuralShell Operator Guide').first().waitFor({ state: 'visible', timeout: 15000 });
    record('help-works', true);

    await composer.fill('freeform b2 smoke', { force: true });
    const send = page.getByRole('button', { name: 'Send' }).first();
    await send.waitFor({ state: 'visible' });
    await send.click({ force: true });
    record('freeform-works', true);

    report.overall = report.checks.every((c) => c.pass) ? 'pass' : 'fail';
    fs.writeFileSync(path.join(PROOF_DIR, 'runtime-smoke-report.json'), `${JSON.stringify(report, null, 2)}\n`);
    await app.close();
    fs.rmSync(userDataDir, { recursive: true, force: true });
    console.log(JSON.stringify(report));
    process.exit(report.overall === 'pass' ? 0 : 1);
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});

