/**
 * P2-LAZY-B3 focused Electron runtime smoke (local proof, gitignored).
 */
const { _electron: electron } = require('playwright');
const fs = require('fs');
const path = require('path');
const os = require('os');

const PROOF_DIR = __dirname;
const repoRoot = path.join(__dirname, '../../..');

async function dismissOverlays(page) {
    for (const id of ['onboarding-close-btn', 'firstboot-close-btn']) {
        const btn = page.getByTestId(id);
        if (await btn.count()) await btn.first().click({ force: true }).catch(() => {});
    }
    await page.keyboard.press('Escape').catch(() => {});
}

async function openAle(page) {
    await page.getByTestId('adaptive-layout-open-btn').click({ force: true });
    await page.getByTestId('adaptive-layout-engine').waitFor({ state: 'visible', timeout: 20000 });
}

async function main() {
    const report = {
        phase: 'p2-lazy-b3-ale-polish',
        head: 'dd3d34b',
        date: new Date().toISOString(),
        checks: [],
        consoleErrors: [],
        pageErrors: [],
        overall: 'fail',
    };
    const record = (id, pass, note = '') => report.checks.push({ id, pass, note });

    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-b3-ale-'));
    const app = await electron.launch({
        args: ['.'],
        cwd: repoRoot,
        env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1' },
    });
    const page = await app.firstWindow();
    page.on('pageerror', (err) => report.pageErrors.push(String(err)));
    page.on('console', (msg) => {
        if (msg.type() === 'error') report.consoleErrors.push(msg.text());
    });

    await page.setViewportSize({ width: 1440, height: 900 });
    await page.evaluate(() => {
        globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        globalThis.localStorage.setItem('neuralshell_first_boot_dismissed_v1', '1');
    });
    await page.reload();
    await page.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 45000 });
