    record('layout-chip-opens-ale', true);

    const scope = page.locator('#adaptive-layout-engine-recovery-scope');
    record('recovery-callout-visible', await scope.isVisible());
    const scopeText = (await scope.innerText()).toLowerCase();
    record('recovery-callout-mission-eco-tasks', scopeText.includes('mission') && scopeText.includes('eco'));

    const operatorCard = page.getByRole('button', { name: /Operator/i }).filter({ hasText: 'Rail bar: Spacious' });
    record('rail-badge-operator-spacious', await operatorCard.count() > 0);

    const hudCard = page.getByRole('button', { name: /HUD \/ Cockpit/i }).filter({ hasText: 'Rail bar: HUD' });
    record('rail-badge-hud', await hudCard.count() > 0);

