    record('non-wired-toggle-disabled', await disabledAmbient.count() > 0);
    record('non-wired-label', await page.getByText('not wired in recovery shell').first().isVisible());

    const liveSmart = page.locator('text=Smart Suggestions').locator('..').getByText('live', { exact: true });
    record('live-label-visible', await liveSmart.count() > 0);

    const beforeRails = await page.evaluate(() => {
        const thread = document.querySelector('[data-testid="thread-rail"]');
        const wideBtn = document.querySelector('[data-testid="layout-preset-wide-btn"]');
        return {
            threadWidth: thread ? thread.getBoundingClientRect().width : 0,
            widePressed: wideBtn ? wideBtn.getAttribute('aria-pressed') === 'true' : false,
        };
    });

    await page.getByRole('button', { name: 'Presets', exact: true }).click();
    await operatorCard.first().click({ force: true });
    await page.waitForTimeout(600);

    const afterRails = await page.evaluate(() => {
        const thread = document.querySelector('[data-testid="thread-rail"]');
        const wideBtn = document.querySelector('[data-testid="layout-preset-wide-btn"]');
        return {
            threadWidth: thread ? thread.getBoundingClientRect().width : 0,
            widePressed: wideBtn ? wideBtn.getAttribute('aria-pressed') === 'true' : false,
        };
    });
    report.operatorApply = { before: beforeRails, after: afterRails };
    record(
        'operator-preset-applies-spacious',
        afterRails.widePressed && afterRails.threadWidth >= beforeRails.threadWidth,
        `wide=${afterRails.widePressed} thread ${beforeRails.threadWidth}->${afterRails.threadWidth}`,
    );

    await page.locator('[data-testid="adaptive-layout-engine"] button[data-accessible-overlay-close]').click({ force: true });
    await page.getByTestId('adaptive-layout-engine').waitFor({ state: 'hidden', timeout: 5000 });
    record('x-closes-ale', true);

    await openAle(page);
    await page.locator('[data-testid="adaptive-layout-engine"]').click({ position: { x: 10, y: 10 } });
    await page.keyboard.press('Escape');
    await page.getByTestId('adaptive-layout-engine').waitFor({ state: 'hidden', timeout: 5000 });
    record('escape-closes-ale', true);

    await page.getByTestId('mission-control-open-btn').click();
    await page.getByTestId('mission-control').waitFor({ state: 'visible' });
    await page.getByTestId('mission-control-close-btn').click();
    await page.getByTestId('ecosystem-open-btn').click();
    await page.getByTestId('ecosystem-launcher').waitFor({ state: 'visible' });
    await page.getByTestId('ecosystem-close-btn').click();
    await page.getByTestId('task-manager-open-btn').click();
    await page.getByTestId('task-manager-drawer').waitFor({ state: 'visible' });
    await page.getByTestId('task-manager-close-btn').click();
    record('mission-eco-tasks', true);

    await page.getByTitle('Projects (Ctrl+P)').click({ force: true });
    await page.getByTestId('projects-mode-panel').waitFor({ state: 'visible', timeout: 10000 });
    await page.keyboard.press('Escape');
    await page.getByTitle('Agent Marketplace').click({ force: true });
    await page.getByTestId('agent-store').waitFor({ state: 'visible', timeout: 10000 });
    await page.keyboard.press('Escape');
    await page.getByTitle('Voice input').click({ force: true });
    await page.getByTestId('voice-mode').waitFor({ state: 'visible', timeout: 15000 }).catch(() => {});
    await page.keyboard.press('Escape');
    record('projects-agents-voice', true);

    await page.getByTestId('command-palette-btn').click();
    await page.getByTestId('command-palette').waitFor({ state: 'visible' });
    await page.keyboard.press('Escape');
    record('exec-palette', true);

    await page.keyboard.press('Control+,');
    await page.getByTestId('settings-drawer').waitFor({ state: 'visible' });
    await page.keyboard.press('Escape');
    record('settings-opens', true);

    const composer = page.getByTestId('chat-input').first();
    await composer.fill('/help', { force: true });
    await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
    await page.getByText('NeuralShell Operator Guide').first().waitFor({ state: 'visible', timeout: 20000 });
    record('help-works', true);

    await composer.fill('freeform b3 smoke', { force: true });
    await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
    record('freeform-works', true);

    const fatalConsole = report.consoleErrors.filter((t) => !/Autofill\.|DevTools|favicon/i.test(t));
    record('no-fatal-console', fatalConsole.length === 0, fatalConsole.slice(0, 3).join(' | '));
    record('no-react-page-errors', report.pageErrors.length === 0, report.pageErrors.slice(0, 2).join(' | '));

    report.overall = report.checks.every((c) => c.pass) ? 'pass' : 'fail';
    fs.writeFileSync(path.join(PROOF_DIR, 'runtime-smoke-report.json'), `${JSON.stringify(report, null, 2)}\n`);
    fs.writeFileSync(
        path.join(PROOF_DIR, 'ELECTRON-SMOKE.md'),
        `# B3 Electron runtime smoke\n\n- **Overall:** ${report.overall}\n- **Date:** ${report.date}\n- **HEAD:** ${report.head}\n\nSee \`runtime-smoke-report.json\` for per-check results.\n`,
    );
    await app.close();
    fs.rmSync(userDataDir, { recursive: true, force: true });
    console.log(JSON.stringify(report, null, 2));
    process.exit(report.overall === 'pass' ? 0 : 1);
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});

