/**
 * OCL-A panel bus migration — focused Electron runtime smoke (local proof).
 */
const { _electron: electron } = require('playwright');
const fs = require('fs');
const path = require('path');
const os = require('os');

const PROOF_DIR = __dirname;
const repoRoot = path.join(__dirname, '../../..');

async function dismissOverlays(page) {
    for (const id of ['onboarding-close-btn', 'firstboot-close-btn']) {
        const btn = page.getByTestId(id);
        if (await btn.count()) await btn.first().click({ force: true }).catch(() => {});
    }
    await page.keyboard.press('Escape').catch(() => {});
}

async function main() {
    const report = {
        phase: 'ocl-a-panel-bus-migration',
        date: new Date().toISOString(),
        checks: [],
        consoleErrors: [],
        pageErrors: [],
        overall: 'fail',
    };
    const record = (id, pass, note = '') => report.checks.push({ id, pass, note });

    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-ocl-a-'));
    const app = await electron.launch({
        args: ['.'],
        cwd: repoRoot,
        env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1' },
    });
    const page = await app.firstWindow();
    page.on('pageerror', (err) => report.pageErrors.push(String(err)));
    page.on('console', (msg) => {
        if (msg.type() === 'error') report.consoleErrors.push(msg.text());
    });

    await page.setViewportSize({ width: 1440, height: 900 });
    await page.evaluate(() => {
        globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        globalThis.localStorage.setItem('neuralshell_first_boot_dismissed_v1', '1');
    });
    await page.reload();
    await page.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 45000 });
    await dismissOverlays(page);

    await page.getByTestId('mission-control-open-btn').click({ force: true });
    await page.getByTestId('mission-control').waitFor({ state: 'visible', timeout: 15000 });
    record('mission-chip-opens', true);

    await page.getByTestId('ecosystem-open-btn').click({ force: true });
    await page.getByTestId('ecosystem-launcher').waitFor({ state: 'visible', timeout: 15000 });
    const missionStillVisible = await page.getByTestId('mission-control').isVisible();
    record('mission-then-eco-no-stack', !missionStillVisible, `mission visible=${missionStillVisible}`);

    await page.getByTestId('ecosystem-close-btn').click({ force: true });
    await page.getByTestId('ecosystem-launcher').waitFor({ state: 'hidden', timeout: 5000 });

    const composer = page.getByTestId('chat-input').first();
    await composer.fill('/fleet', { force: true });
    await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
    await page.waitForTimeout(800);
    const fleetVisible = await page.locator('[data-testid="fleet-control"], [data-testid*="fleet"]').first().isVisible().catch(() => false);
    record('slash-fleet', fleetVisible);

    await page.keyboard.press('Escape');
    await composer.fill('/recovery', { force: true });
    await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
    await page.waitForTimeout(800);
    record('slash-recovery', await page.getByTestId('recovery-center').isVisible().catch(() => false));
    await page.keyboard.press('Escape');

    await page.getByTestId('settings-open-btn').click({ force: true });
    const moreBtn = page.locator('button').filter({ hasText: /^More$/ }).first();
    if (await moreBtn.count()) {
        await moreBtn.click({ force: true });
        const analyticsBtn = page.getByTestId('analytics-open-btn');
        if (await analyticsBtn.count()) {
            await analyticsBtn.click({ force: true });
            await page.waitForTimeout(500);
            record('more-analytics', true);
            await page.keyboard.press('Escape');
        } else {
            record('more-analytics', false, 'analytics-open-btn not in overflow');
        }
    } else {
        record('more-analytics', false, 'More menu not found');
    }
    await page.keyboard.press('Escape');

    await page.locator('button[title="Projects (Ctrl+P)"]').click({ force: true });
    await page.getByTestId('recovery-panel-projects-mode').waitFor({ state: 'visible', timeout: 15000 });
    record('p0-projects', true);
    await page.getByTestId('recovery-panel-projects-mode').getByLabel('Close panel').click();
    await page.locator('button[title="Agent Marketplace"]').click({ force: true });
    await page.getByTestId('agent-store').waitFor({ state: 'visible', timeout: 30000 });
    record('p0-agents', true);
    await page.keyboard.press('Escape');

    await page.getByTestId('adaptive-layout-open-btn').click({ force: true });
    await page.getByTestId('adaptive-layout-engine').waitFor({ state: 'visible', timeout: 15000 });
    await page.keyboard.press('Escape');
    record('layout-ale', true);

    await page.getByTestId('command-palette-btn').click();
    await page.getByTestId('command-palette').waitFor({ state: 'visible' });
    await page.keyboard.press('Escape');
    record('exec-palette', true);

    await page.keyboard.press('Control+,');
    await page.getByTestId('settings-drawer').waitFor({ state: 'visible' });
    await page.keyboard.press('Escape');
    record('settings', true);

    await composer.fill('/help', { force: true });
    await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
    await page.getByText('NeuralShell Operator Guide').first().waitFor({ state: 'visible', timeout: 20000 });
    record('help', true);

    await composer.fill('ocl-a smoke', { force: true });
    await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
    record('freeform', true);

    const fatalConsole = report.consoleErrors.filter(
        (t) => !/Autofill\.|DevTools|favicon|worldtimeapi|timeapi\.io|connect-src 'none'|ws:\/\/127\.0\.0\.1/i.test(t),
    );
    record('no-fatal-console', fatalConsole.length === 0, fatalConsole.slice(0, 2).join(' | '));
    record('no-page-errors', report.pageErrors.length === 0, report.pageErrors.slice(0, 2).join(' | '));

