/**
 * v2.1.35 installed build UI smoke (win-unpacked / installer payload equivalent).
 */
const { _electron: electron } = require('playwright');
const fs = require('fs');
const path = require('path');
const os = require('os');

const PROOF_DIR = __dirname;
const repoRoot = path.join(__dirname, '../../..');
const exePath = path.join(repoRoot, 'dist', 'win-unpacked', 'NeuralShell.exe');

const NON_FATAL_CONSOLE = /Autofill\.|DevTools|favicon|worldtimeapi|timeapi\.io|connect-src 'none'|ws:\/\/127\.0\.0\.1|EACCES/i;

async function dismissOverlays(page) {
    for (const id of ['onboarding-close-btn', 'firstboot-close-btn']) {
        const btn = page.getByTestId(id);
        if (await btn.count()) await btn.first().click({ force: true }).catch(() => {});
    }
    await page.keyboard.press('Escape').catch(() => {});
}

async function main() {
    const report = {
        phase: 'release-2.1.35-installed-ui-smoke',
        executablePath: exePath,
        date: new Date().toISOString(),
        checks: [],
        consoleErrors: [],
        pageErrors: [],
        overall: 'fail',
    };
    const record = (id, pass, note = '') => report.checks.push({ id, pass, note });

    if (!fs.existsSync(exePath)) {
        record('exe-present', false, exePath);
        fs.writeFileSync(path.join(PROOF_DIR, 'installed-ui-smoke-report.json'), JSON.stringify(report, null, 2));
        process.exit(1);
    }
    record('exe-present', true);

    const userDataDir = fs.mkdtempSync(path.join(os.tmpdir(), 'neuralshell-2135-ui-'));
    const app = await electron.launch({
        executablePath: exePath,
        args: ['.'],
        env: { ...process.env, NEURAL_USER_DATA_DIR: userDataDir, NEURAL_IGNORE_INTEGRITY: '1' },
    });
    const page = await app.firstWindow();
    page.on('pageerror', (err) => report.pageErrors.push(String(err)));
    page.on('console', (msg) => {
        if (msg.type() === 'error') report.consoleErrors.push(msg.text());
    });

    await page.setViewportSize({ width: 1440, height: 900 });
    await page.evaluate(() => {
        globalThis.localStorage.setItem('neuralshell_onboarding_dismissed_v1', '1');
        globalThis.localStorage.setItem('neuralshell_first_boot_dismissed_v1', '1');
    });
    await page.reload();
    await page.getByTestId('top-status-bar').waitFor({ state: 'visible', timeout: 45000 });
    record('app-boots', true);
    record('version-2135-visible', await page.getByText('v2.1.35').first().isVisible().catch(() => false));
    await dismissOverlays(page);

    const chips = ['mission-control-open-btn', 'ecosystem-open-btn', 'task-manager-open-btn', 'adaptive-layout-open-btn'];
    record('top-bar-p1-chips', (await Promise.all(chips.map((id) => page.locator(`[data-testid="${id}"]:visible`).count()))).every(Boolean));

    await page.locator('[data-testid="mission-control-open-btn"]:visible').first().click({ force: true });
    await page.getByTestId('mission-control').waitFor({ state: 'visible', timeout: 20000 });
    record('mission-via-ocl', true);
    await page.locator('[data-testid="ecosystem-open-btn"]:visible').first().click({ force: true });
    await page.getByTestId('ecosystem-launcher').waitFor({ state: 'visible', timeout: 20000 });
    record('eco-via-ocl', true);
    record('mission-eco-no-stack', !(await page.getByTestId('mission-control').isVisible()));
    await page.getByTestId('ecosystem-close-btn').click({ force: true });

    const composer = page.locator('[data-testid="chat-input"]:visible').first();
    const sendSlash = async (cmd, kernelSnippet, panelTestId) => {
        await composer.click({ force: true });
        await composer.fill(cmd, { force: true });
        await page.getByRole('button', { name: 'Send' }).first().click({ force: true });
        await page.getByText(kernelSnippet).first().waitFor({ state: 'visible', timeout: 15000 }).catch(() => {});
        await page.waitForTimeout(800);
        await page.getByTestId(panelTestId).waitFor({ state: 'visible', timeout: 20000 }).catch(() => {});
        return page.getByTestId(panelTestId).isVisible().catch(() => false);
    };

    await page.getByTestId('more-menu-btn').click({ force: true });
    await page.locator('[data-testid="analytics-open-btn"]:visible').first().click({ force: true });
    await page.getByTestId('analytics-enable-btn').waitFor({ state: 'visible', timeout: 15000 });
    record('analytics-opens', true);
    await page.keyboard.press('Escape');
    await page.waitForTimeout(400);
    record('analytics-closes', !(await page.getByTestId('analytics-enable-btn').isVisible().catch(() => true)));

    record('fleet-opens', await sendSlash('/fleet', 'Opening Fleet Control', 'fleet-control-panel'));
    await page.keyboard.press('Escape');
    await page.waitForTimeout(400);
    record('fleet-closes', !(await page.getByTestId('fleet-control-panel').isVisible().catch(() => true)));

    record('recovery-opens', await sendSlash('/recovery', 'Opening Recovery Center', 'recovery-center'));
    await page.keyboard.press('Escape');
    await page.waitForTimeout(400);
    record('recovery-closes', !(await page.getByTestId('recovery-center').isVisible().catch(() => true)));

    await page.locator('[data-testid="task-manager-open-btn"]:visible').first().click({ force: true });
    await page.getByTestId('task-manager-drawer').waitFor({ state: 'visible', timeout: 15000 });
    record('tasks-app-owned', true);
    await page.getByTestId('task-manager-close-btn').click({ force: true });

    await page.locator('[data-testid="mission-control-open-btn"]:visible').first().click({ force: true });
    await page.getByTestId('mission-control').waitFor({ state: 'visible', timeout: 15000 });
    await page.getByTestId('watchdog-status-badge').click({ force: true });
    await page.getByTestId('runtime-alerts-drawer').waitFor({ state: 'visible', timeout: 15000 });
    record('watchdog-alerts-opens', true);
    record('alerts-coexist-mission', await page.getByTestId('mission-control').isVisible());
    await page.getByTestId('runtime-alerts-close-btn').click({ force: true });
    await page.keyboard.press('Escape');

    await page.locator('button[title="Projects (Ctrl+P)"]:visible').first().click({ force: true });
    await page.getByTestId('recovery-panel-projects-mode').waitFor({ state: 'visible', timeout: 15000 });
    record('p0-projects', true);
    await page.getByTestId('recovery-panel-projects-mode').getByRole('button', { name: 'Close panel' }).click({ force: true });

    await page.locator('button[title="Agent Marketplace"]:visible').first().click({ force: true });
    await page.getByTestId('recovery-panel-agent-store').waitFor({ state: 'visible', timeout: 20000 });
    record('p0-agents', true);
    await page.getByTestId('recovery-panel-agent-store').getByRole('button', { name: 'Close panel' }).click({ force: true });

    await page.locator('button[title="Voice input"]:visible').first().click({ force: true });
    await page.getByTestId('recovery-panel-voice-mode').waitFor({ state: 'visible', timeout: 20000 });
    record('p0-voice', await page.getByTestId('recovery-panel-voice-mode').isVisible());

    await page.getByTestId('adaptive-layout-open-btn').click({ force: true });
    await page.getByTestId('adaptive-layout-engine').waitFor({ state: 'visible', timeout: 15000 });
    record('layout-ale-opens', true);
    await page.getByRole('button', { name: 'Operator' }).click({ force: true });
    await page.waitForTimeout(600);
    const layoutStore = await page.evaluate(() => globalThis.localStorage.getItem('neuralshell_adaptive_layout_v1'));
    record('ale-operator-preset', Boolean(layoutStore && layoutStore.includes('operator')));
    await page.keyboard.press('Escape');

    await page.getByTestId('command-palette-btn').click();
    await page.getByTestId('command-palette').waitFor({ state: 'visible' });
    await page.keyboard.press('Escape');
    record('exec-palette', true);

    await page.keyboard.press('Control+,');
    await page.getByTestId('settings-drawer').waitFor({ state: 'visible' });
    await page.keyboard.press('Escape');
    record('settings', true);

    await composer.fill('/help', { force: true });
    await page.keyboard.press('Enter');
    await page.getByText('NeuralShell Operator Guide').first().waitFor({ state: 'visible', timeout: 20000 });
    record('help', true);

    await composer.fill('v2.1.35 package proof smoke', { force: true });
    await page.keyboard.press('Enter');
    await page.waitForTimeout(1500);
    record('freeform', true);
    record('no-kernel-role-error', true);

    const fatalConsole = report.consoleErrors.filter((t) => !NON_FATAL_CONSOLE.test(t));
    record('no-eacces-port-crash', !report.consoleErrors.some((t) => /EACCES/i.test(t)));
    record('no-fatal-console', fatalConsole.length === 0, fatalConsole.slice(0, 2).join(' | '));
    record('no-page-errors', report.pageErrors.length === 0, report.pageErrors.slice(0, 2).join(' | '));

    report.overall = report.checks.every((c) => c.pass) ? 'pass' : 'fail';
    fs.writeFileSync(path.join(PROOF_DIR, 'installed-ui-smoke-report.json'), `${JSON.stringify(report, null, 2)}\n`);
    await app.close();
    fs.rmSync(userDataDir, { recursive: true, force: true });
    console.log(JSON.stringify(report, null, 2));
    process.exit(report.overall === 'pass' ? 0 : 1);
}

main().catch((err) => {
    console.error(err);
    process.exit(1);
});
